#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
	int t;
	cin>>t;
	while(t--){
	  int n;
	  cin>>n;
	  int N = 3*n;
	  vector<ll>arr(N);
	  
	  for(auto&x :arr)cin>>x;
	  
	  sort(arr.rbegin(),arr.rend());
	  
	  vector<ll>pref(N+1,0);
	  for(int i=0;i<N;i++){
	      pref[i+1]=pref[i]+arr[i];
	  }
	  ll ans = 0;
	  for(int m = 0;m<=n;m++){
	      int num1 = n-m;
	      int num2 =0;
	      
	      auto del = [&](int x)->ll{
	          int j=3*n-2*m-x-1;
	          return arr[m+2*x]+arr[m+2*x+1]-3LL*arr[j];
	      };
	      
	      if(num1==0){
	          num2=0;
	      }else if(del(num1-1)>=0){
	          num2 = num1;
	      }
	      else if(del(0)<0){
	          num2=0;
	      }
	      else{
	          int l = 0,h=num1-1;
	          while(l<h){
	              int mid = (l+h+1)/2;
	              if(del(mid)>=0)l=mid;
	              else
	               h=mid-1;
	          }
	          num2=l+1;
	          
	      }
	      ll cur = 6LL*pref[m]+4LL*(pref[m+2*num2]-pref[m])+3LL*(pref[3*n-2*m-num2]-pref[m+2*num2]);
	      ans = max(ans,cur);
	  }
	  cout<<ans<<endl;
	}
	return 0;

}
